using Microsoft.EntityFrameworkCore;using GrapheneTrace.Areas.Identity.Data;using GrapheneTrace.Services.Interfaces;using GrapheneTrace.Models.Admin;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc.Rendering;using GrapheneTrace.Data; using GrapheneTrace.Models.Database; using GrapheneTrace.Enums;using GrapheneTrace.Models;namespace GrapheneTrace.Services{    public class AdminService : IAdminService    {        private readonly ApplicationDbContext _context;        private readonly UserManager<ApplicationUser> _userManager;        public AdminService(UserManager<ApplicationUser> userManager, ApplicationDbContext context)        {            _userManager = userManager;            _context = context;        }        /// <summary>        /// Update user database entry with provided EditUserViewModel        /// </summary>        /// <param name="model"></param>         /// <returns></returns>        public async Task<bool> UpdateUser(EditUserViewModel model)        {            var user = await _userManager.FindByIdAsync(model.Id.ToString());            if (user == null)                return false;            user.Email = model.Email;            user.UserName = model.Email;            user.DateOfBirth = model.DateOfBirth;            user.Name = model.Name;            var userRoles = await _userManager.GetRolesAsync(user);            await _userManager.AddToRolesAsync(user, model.SelectedRoles.Except(userRoles));            await _userManager.RemoveFromRolesAsync(user, userRoles.Except(model.SelectedRoles));            if (!string.IsNullOrEmpty(model.NewPassword))            {                if (model.NewPassword != model.ConfirmPassword)                    return false;                foreach (var validator in _userManager.PasswordValidators)                {                    var result = await validator.ValidateAsync(_userManager, user, model.NewPassword);                    if (!result.Succeeded)                    {                        return false;                    }                }                                await _userManager.RemovePasswordAsync(user);                await _userManager.AddPasswordAsync(user, model.NewPassword);            }            var updateResult = await _userManager.UpdateAsync(user);            return updateResult.Succeeded;        }                /// <summary>        /// Update the links between patients and clinicians        /// </summary>        /// <param name="idsToAdd"></param> The links to add        /// <param name="idsToRemove"></param> The links to remove        /// <param name="primaryUserId"></param> Who are we linking to?        /// <param name="isClinician"></param> Is the user we are linking to a clinician?        public async Task UpdatePatientClinicianLinks(List<int> idsToAdd, List<int> idsToRemove, int primaryUserId, bool isClinician)        {            if (idsToAdd.Count > 0)            {                var newLinks = idsToAdd.Select(id => isClinician switch                {                    true  => new PatientClinician { PatientId = primaryUserId, ClinicianId = id },                    false => new PatientClinician { PatientId = id, ClinicianId = primaryUserId }                });                _context.PatientClinician.AddRange(newLinks);            }            if (idsToRemove.Count > 0)            {                var linksToRemoveQuery = isClinician switch                {                    true => _context.PatientClinician.Where(pc =>                        pc.PatientId == primaryUserId && idsToRemove.Contains(pc.ClinicianId)),                    false => _context.PatientClinician.Where(pc =>                        pc.ClinicianId == primaryUserId && idsToRemove.Contains(pc.PatientId))                };                var linksToRemove = await linksToRemoveQuery.ToListAsync();                _context.PatientClinician.RemoveRange(linksToRemove);            }            await _context.SaveChangesAsync();        }        /// <summary>        /// Return all users linked to a specific user        /// </summary>        /// <param name="id"></param> The id of the user we want to find the links of        /// <param name="type"></param> The type of that user        /// <returns></returns>        public async Task<List<int>> GetAlreadyLinkedUsers(int id, UserType type)        {            return type switch            {                UserType.Clinician => await _context.PatientClinician.Where(pc => pc.PatientId == id)                    .Select(pc => pc.ClinicianId)                    .ToListAsync(),                UserType.Patient => await _context.PatientClinician.Where(pc => pc.ClinicianId == id)                    .Select(pc => pc.PatientId)                    .ToListAsync(),                _ => []            };        }        /// <summary>        /// Get the available or already assigned links of a certain user        /// </summary>        /// <param name="userType"></param> The type of User        /// <param name="userId"></param> The User's id        /// <param name="filterMode"></param> The filter: Assigned or Available        /// <returns></returns>        public async Task<IList<SelectListItem>> GetLinkSelectionList(UserType userType, int userId, LinkFilter filterMode)        {            // Get all the Users with the user type userType            var allUsers = await _userManager.GetUsersInRoleAsync(userType.ToString());            // Convert to HashSet for O(1) lookup            var linkedIdsSet = new HashSet<int>(await GetAlreadyLinkedUsers(userId, userType));            // Filter the hashset of linkedIds             var filteredUsers = filterMode switch            {                LinkFilter.Assigned  => allUsers.Where(u => linkedIdsSet.Contains(u.Id)),                 LinkFilter.Available => allUsers.Where(u => !linkedIdsSet.Contains(u.Id)),                _                    => []            };            return filteredUsers                .Select(u => new SelectListItem                {                    Text = $"{u.Name} ({u.Email})",                    Value = u.Id.ToString()                })                .ToList();        }                /// <summary>        /// Get all the users to be displayed on the admin dashboard        /// </summary>        /// <param name="searchString"></param> The string used to search for users        /// <returns></returns>        public async Task<List<UserViewModel>> GetAdminDashboardUsersAsync(string searchString)        {            var query = _context.Users.AsNoTracking();                        if (!string.IsNullOrWhiteSpace(searchString))            {                var isIdSearch = int.TryParse(searchString, out var searchId);                query = query.Where(u =>                    (isIdSearch && u.Id == searchId) ||                     u.Email.Contains(searchString) ||                    u.Name.Contains(searchString) ||                    _context.UserRoles                        .Where(ur => ur.UserId == u.Id)                        .Join(_context.Roles, ur => ur.RoleId, r => r.Id, (ur, r) => r.Name)                        .Any(rName => rName.Contains(searchString))                );            }                        var users = await query.Select(u => new UserViewModel                {                    Id = u.Id,                    Email = u.Email ?? "",                    Name = u.Name,                    DateOfBirth = u.DateOfBirth,                                        PatientLinkCount = _context.PatientClinician.Count(pc => pc.PatientId == u.Id),                    ClinicianLinkCount = _context.PatientClinician.Count(pc => pc.ClinicianId == u.Id),                                        Roles = _context.UserRoles                        .Where(ur => ur.UserId == u.Id)                        .Join(_context.Roles, ur => ur.RoleId, r => r.Id, (ur, r) => r.Name)                        .ToList()                })                .ToListAsync();            return users;        }        /// <summary>        /// Create a new user        /// </summary>        /// <param name="model"></param> CreateUserViewModel containing details of new user        /// <returns></returns>        public async Task<IdentityResult> CreateUser(CreateUserViewModel model)        {            var user = new ApplicationUser            {                UserName = model.Email,                Email = model.Email,                Name = model.Name,                DateOfBirth = model.DateOfBirth,                EmailConfirmed = true            };                        var createResult = await _userManager.CreateAsync(user, model.Password);            if (!createResult.Succeeded)            {                return createResult;             }                        var roleResult = await _userManager.AddToRoleAsync(user, model.SelectedRole);            if (roleResult.Succeeded) return IdentityResult.Success;            await _userManager.DeleteAsync(user);                    return roleResult;        }                /// <summary>        /// Delete a user        /// </summary>        /// <param name="targetUserId"></param> The user to be deleted        /// <param name="currentId"></param> The id of the user doing the deleting         /// <returns></returns>        public async Task<DeleteUserStatus> DeleteUserAsync(int targetUserId, int currentId)        {            if (targetUserId == currentId)            {                return DeleteUserStatus.CannotDeleteSelf;            }                        var user = await _userManager.FindByIdAsync(targetUserId.ToString());                        if (user == null)            {                return DeleteUserStatus.UserNotFound;            }                        var result = await _userManager.DeleteAsync(user);            return !result.Succeeded ? DeleteUserStatus.DatabaseError : DeleteUserStatus.Success;        }    }}